import { _decorator, Component, Node } from 'cc';
import { Bus } from './Engine/Bus';
import { World } from './Engine/World';
import { ViewRegistry } from './Engine/ViewRegistry';
import { FixedTick } from './Engine/Tick';
import { GameData } from './Core/Data/GameData';
import { Plane } from './Battle/Entity/Plane';
import { MovementSystem } from './Battle/System/MovementSystem';
import { OutOfBoundsSystem } from './Battle/System/OutOfBoundsSystem';
import { FireSystem } from './Battle/System/FireSystem';
import { SpawnSystem } from './Battle/System/SpawnSystem';
import { BulletView } from './Battle/View/BulletView';

const { ccclass } = _decorator;

@ccclass('BattleTest')
export class BattleTest extends Component {

    start() {
        GameData.init();

        const bus = new Bus();
        const views = new ViewRegistry(this.node);
        views.registerFactory('bullet', (e) => {
            const node = new Node(`bullet_${e.id}`);
            return node.addComponent(BulletView);
        });
        // 玩家还没有 View，但先注册一个空的，避免 warn
        views.registerFactory('player', () => null as any);

        const world = new World(bus, views);

        // ⭐ System 顺序很重要
        world.addSystem(new FireSystem());            // 1. 先开火
        world.addSystem(new SpawnSystem());           // 2. 生成子弹
        world.addSystem(new MovementSystem());        // 3. 移动所有子弹
        world.addSystem(new OutOfBoundsSystem());     // 4. 清理越界

        // 创建玩家
        const player = new Plane('player');
        player.x = 0;
        player.y = -GameData.viewH / 2 + 100;
        player.weapons.push({
            fireInterval: 0.2,           // 每 0.2 秒一发
            cooldownTimer: 0,
            bulletType: 'blue',
            bulletSpeed: 400,
            bulletDamage: 10,
            fireDirX: 0,
            fireDirY: 1,
            enabled: true,
        });
        world.add(player);

        const tick = this.node.addComponent(FixedTick);
        tick.setup(world, views);
        tick.begin();
    }
}